<?php
namespace Tests\Feature;
use App\Models\AffiliateConversion;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AffiliatePostbackTest extends TestCase{use RefreshDatabase;public function test_postback_requires_secret():void{config(['services.affiliate.postback_secret'=>'test-secret']);$this->postJson('/api/integration/v1/affiliate/postback',['conversion_id'=>'CV-1'])->assertForbidden();}public function test_postback_upserts_conversion_without_duplicates():void{config(['services.affiliate.postback_secret'=>'test-secret']);$payload=['conversion_id'=>'CV-1','transaction_id'=>'TX-1','conversion_status'=>'pending','conversion_sale_amount'=>20000000,'conversion_publisher_payout'=>500000,'aff_sub1'=>'RD260001'];$this->withHeader('X-Affiliate-Secret','test-secret')->postJson('/api/integration/v1/affiliate/postback',$payload)->assertOk()->assertJsonPath('ok',true);$payload['conversion_status']='approved';$this->withHeader('X-Affiliate-Secret','test-secret')->postJson('/api/integration/v1/affiliate/postback',$payload)->assertOk();$this->assertDatabaseCount('affiliate_conversions',1);$this->assertSame('approved',AffiliateConversion::first()->conversion_status);}}
